$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-15mini-filter-probe.mjs'
try {[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log('{"status":"timeout"}');process.exit(0)},7000);
try {
const t=(await(await fetch('http://127.0.0.1:17447/json/list')).json()).find(x=>x.id==='D229F01C94F7F6DF012309BB4CE211CD');
if(!t)throw Error('TARGET_NOT_FOUND');
const w=new WebSocket(t.webSocketDebuggerUrl);
w.addEventListener('open',()=>w.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:"(()=>({url:location.href,query:location.search,title:document.title,activeButtons:Array.from(document.querySelectorAll('button,[role=button]')).filter(x=>(x.textContent||'').trim()==='Частные').slice(0,2).map(x=>({html:x.outerHTML.slice(0,500)}))}))()",returnByValue:true}})),{once:true});
w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(z.id===1){console.log(JSON.stringify(z.result?.result?.value||{error:'eval_failed'}));process.exit(0)}});
} catch(e){console.log(JSON.stringify({error:String(e).slice(0,90)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false)); & node.exe $tmp} finally {Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
